(() => {
  'use strict';

  const UI={
    version:'2.5.1',
    namespace:'acgn_visual_v25',
    rootId:'avs-v25-floating-inspector',
    styleId:'avs-v25-floating-inspector-style',
    root:null,ball:null,panel:null,content:null,dot:null,doc:null,win:null,
    open:false,selectedId:null,tab:'overview',search:'',drag:null,poll:null,
    lastRevision:-1,listeners:[],domListeners:[],observer:null,rescanning:false
  };

  if (globalThis.__AVS_V25_INSPECTOR__) {
    try { globalThis.__AVS_V25_INSPECTOR__.stop?.(); } catch (_) {}
  }
  globalThis.__AVS_V25_INSPECTOR__=UI;

  const ACC=[
    ['headwear','头饰'],['forehead','额饰'],['hair','发饰'],['ears','耳饰'],['neck','颈饰'],
    ['shoulders','肩饰'],['arms','臂饰'],['wrists','腕饰'],['hands','手饰'],['fingers','指饰'],
    ['chest','胸饰'],['back','背饰'],['waist','腰饰'],['hips','胯饰'],['thighs','大腿饰'],
    ['legs','腿饰'],['ankles','踝饰'],['feet','足饰']
  ];
  const TABS=[['overview','概览'],['face','外貌'],['body','身体'],['outfit','穿搭'],['hair','发妆'],['accessory','配饰'],['state','状态']];

  function hostDoc(){try{if(globalThis.parent&&globalThis.parent!==globalThis&&globalThis.parent.document?.body)return globalThis.parent.document}catch(_){}return null}
  function hostWin(d){try{return d?.defaultView||globalThis.parent||null}catch(_){return null}}
  function contextActive(){
    try{
      const s=globalThis.SillyTavern,c=s?.getContext?.(),x=c&&typeof c==='object'?{...s,...c}:s;
      if(!x)return false;if(String(x.groupId??'').trim())return true;
      const raw=x.characterId;if(raw===undefined||raw===null||String(raw).trim()==='')return false;
      const i=Number(raw);return Number.isInteger(i)&&i>=0&&!!x.characters?.[i];
    }catch(_){return false}
  }
  function state(){try{return getVariables({type:'chat'})?.[UI.namespace]||null}catch(_){return null}}
  function prefs(){try{return getVariables({type:'script'})?.avs_v25_ui||{}}catch(_){return{}}}
  function savePrefs(p){try{updateVariablesWith(v=>{v.avs_v25_ui={...(v.avs_v25_ui||{}),...p};return v},{type:'script'})}catch(_){}}

  function make(tag,cls='',txt=''){const e=UI.doc.createElement(tag);if(cls)e.className=cls;if(txt!==undefined&&txt!=='')e.textContent=txt;return e}
  function svg(type){
    const ns='http://www.w3.org/2000/svg',s=UI.doc.createElementNS(ns,'svg'),p=UI.doc.createElementNS(ns,'path');
    s.setAttribute('viewBox','0 0 24 24');p.setAttribute('fill','none');p.setAttribute('stroke','currentColor');p.setAttribute('stroke-width','2');p.setAttribute('stroke-linecap','round');p.setAttribute('stroke-linejoin','round');
    p.setAttribute('d',type==='close'?'M6 6l12 12M18 6L6 18':type==='back'?'M15 18l-6-6 6-6':'M21 21l-4.35-4.35M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0');s.appendChild(p);return s
  }
  function dark(){try{const bg=UI.win.getComputedStyle(UI.doc.body).backgroundColor,m=bg.match(/rgba?\((\d+)[,\s]+(\d+)[,\s]+(\d+)/);if(m)return .2126*+m[1]+.7152*+m[2]+.0722*+m[3]<128;return UI.win.matchMedia?.('(prefers-color-scheme:dark)').matches??false}catch(_){return false}}
  function viewport(){const v=UI.win?.visualViewport;return{w:Math.max(240,v?.width||UI.doc?.documentElement?.clientWidth||UI.win?.innerWidth||360),h:Math.max(320,v?.height||UI.doc?.documentElement?.clientHeight||UI.win?.innerHeight||640)}}
  const clamp=(v,a,b)=>Math.min(Math.max(v,a),Math.max(a,b));

  function positionBall(x,y,save=false){
    if(!UI.ball)return;const{w,h}=viewport(),size=54,safe=10;x=clamp(Number(x)||safe,safe,w-size-safe);y=clamp(Number(y)||safe,safe,h-size-safe);
    UI.ball.style.left=`${x}px`;UI.ball.style.top=`${y}px`;if(save)savePrefs({xr:(x-safe)/Math.max(1,w-size-safe*2),yr:(y-safe)/Math.max(1,h-size-safe*2)});if(UI.open)positionPanel()
  }
  function restoreBall(){const p=prefs(),{w,h}=viewport(),size=54,safe=10,xr=Number.isFinite(+p.xr)?clamp(+p.xr,0,1):.95,yr=Number.isFinite(+p.yr)?clamp(+p.yr,0,1):.67;positionBall(safe+xr*Math.max(1,w-size-safe*2),safe+yr*Math.max(1,h-size-safe*2))}
  function positionPanel(){
    if(!UI.panel||!UI.open)return;const{w,h}=viewport();
    if(w<=640){const ph=Math.min(h*.82,690);UI.panel.style.left='12px';UI.panel.style.top=`${Math.max(12,h-ph-12)}px`;UI.panel.style.width=`${Math.max(240,w-24)}px`;UI.panel.style.height=`${ph}px`}
    else{const pw=Math.min(470,w-32),ph=Math.min(700,h-32),bx=parseFloat(UI.ball.style.left)||20,by=parseFloat(UI.ball.style.top)||80,x=bx+66+pw<=w-14?bx+66:bx-pw-12;UI.panel.style.left=`${clamp(x,14,w-pw-14)}px`;UI.panel.style.top=`${clamp(by-32,14,h-ph-14)}px`;UI.panel.style.width=`${pw}px`;UI.panel.style.height=`${ph}px`}
  }

  function visibleText(v){
    if(v===undefined||v===null||v==='')return'未记录';
    if(Array.isArray(v))return v.length?v.map(visibleText).join('、'):'未佩戴';
    if(typeof v==='number')return String(v);
    if(typeof v!=='string')return'未记录';
    let s=v.replace(/```[\s\S]*?```/g,'').replace(/[{}\[\]`]/g,'').trim();
    s=s.replace(/\b(?:profile|state|design|runtime|ready|processing|degraded|json|api|prompt|schema|path|value|status)\b/gi,'');
    return s.trim()||'未记录';
  }
  function joinNatural(parts){return parts.map(visibleText).filter(x=>x&&x!=='未记录').map(x=>x.replace(/[。；\s]+$/,'')).join('；')+'。'}
  function natural(x){if(!x||typeof x!=='object')return visibleText(x);const parts=[];for(const k of ['form','data','design','beauty'])if(x[k])parts.push(x[k]);return parts.length?joinNatural(parts):'未记录'}
  function garment(x,footwear=false){
    if(!x||x.status==='未穿着')return'未穿着';
    const name=visibleText(x.full_name||x.name||'当前服饰');
    const parts=footwear?[x.specifications,x.design,x.beauty,x.character_effect]:[x.specifications,x.design,x.beauty,x.coverage,x.exposure,x.wearing_feel,x.character_effect];
    return `${name}\n${joinNatural(parts)}`;
  }
  function cosmetic(x){if(!x||x.status==='未着妆')return'未着妆';return joinNatural([x.specifications,x.design,x.beauty,x.character_effect]);}
  const CN=['一','二','三','四','五','六','七','八','九','十','十一','十二'];
  function accessory(a){
    if(!Array.isArray(a)||!a.length)return'未佩戴';
    return a.map((x,i)=>`${CN[i]||String(i+1)}、${visibleText(x.full_name||x.name||'配饰')}\n${joinNatural([x.specifications,x.design,x.beauty,x.character_effect])}`).join('\n\n');
  }

  function facts(c,tab){
    const p=c?.profile||{},f=p.face||{},b=p.body||{},o=p.outfit||{},h=p.hair_makeup||{},a=p.accessories||{},s=p.state||{},n=p.natural_hair||{},q=(k,v)=>({k,v});
    if(tab==='overview')return[
      q('姓名',c?.identity?.name),q('种族',c?.identity?.species),q('外貌年龄',`${c?.identity?.visual_age?.min??'—'}—${c?.identity?.visual_age?.max??'—'}岁`),
      q('整体面貌',f.overall_aesthetic),q('体型',natural(b.body_type)),q('身高',natural(b.height)),q('自然发色',natural(n.color)),q('当前发型',natural(h.hairstyle)),
      q('外衣',garment(o.outerwear)),q('丝袜',garment(o.hosiery)),q('鞋履',garment(o.footwear,true)),q('当前表情',s.current_expression),q('当前整体状态',s.current_overall_state)
    ];
    if(tab==='face')return[
      q('整体面貌',f.overall_aesthetic),q('脸型',natural(f.face_shape)),q('额头',natural(f.forehead)),q('颧区',natural(f.cheekbones)),q('下颌线',natural(f.jawline)),q('下巴',natural(f.chin)),
      q('眉部',natural(f.eyebrows)),q('睫毛',natural(f.eyelashes)),q('眼部',natural(f.eyes)),q('虹膜',natural(f.iris)),q('瞳孔',natural(f.pupil)),q('鼻部',natural(f.nose)),q('唇部',natural(f.lips)),q('肤色',natural(f.skin_tone)),q('肌肤质感',natural(f.skin_texture))
    ];
    if(tab==='body')return[
      ['体型','body_type'],['身高','height'],['头身比例','head_body_ratio'],['肩部','shoulders'],['锁骨','clavicle'],['胸部','bust'],['腰部','waist'],['骨盆','pelvis'],['胯部','hips'],['臀部','buttocks'],
      ['颈部','neck'],['背部曲线','back_curve'],['腹部','abdomen'],['上臂','upper_arms'],['前臂','forearms'],['手部','hands'],['手指','fingers'],['大腿','thighs'],['膝部','knees'],['小腿','calves'],['脚踝','ankles'],['腿长','leg_length'],['足部','feet'],['身体肤色','skin_tone'],['身体肌肤质感','skin_texture']
    ].map(([k,key])=>q(k,natural(b[key])));
    if(tab==='outfit')return[
      q('外衣',garment(o.outerwear)),q('内搭',garment(o.innerwear)),q('胸罩',garment(o.bra)),q('内裤',garment(o.panties)),q('丝袜',garment(o.hosiery)),q('鞋履',garment(o.footwear,true)),
      q('左脚鞋履状态',o.footwear?.left_state),q('右脚鞋履状态',o.footwear?.right_state)
    ];
    if(tab==='hair')return[
      q('自然发长',natural(n.length)),q('自然发色',natural(n.color)),q('当前发型',natural(h.hairstyle)),q('刘海',natural(h.bangs)),q('头发装饰',h.hair_accessories?.status==='未佩戴'?'未佩戴':accessory(h.hair_accessories?.items)),
      q('发型整体效果',h.hair_beauty_summary),q('底妆',cosmetic(h.base_makeup)),q('眼妆',cosmetic(h.eye_makeup)),q('眉妆',cosmetic(h.brow_makeup)),q('腮红',cosmetic(h.blush)),q('唇妆',cosmetic(h.lip_makeup)),q('花钿',cosmetic(h.huadian)),q('妆容整体效果',h.makeup_beauty_summary),q('美甲',h.nails?.status==='未着色'?'未着色':joinNatural([h.nails?.color_and_gloss,h.nails?.beauty]))
    ];
    if(tab==='accessory')return ACC.map(([key,label])=>q(label,accessory(a[key])));
    if(tab==='state')return[
      q('当前表情',s.current_expression),q('当前整体状态',s.current_overall_state),q('当前姿势',s.current_posture),q('当前目光',s.current_gaze),q('当前手势',s.current_gesture),q('当前动作',s.current_motion),q('当前服装状态',s.current_clothing_state),q('当前头发状态',s.current_hair_state),q('当前妆容状态',s.current_makeup_state),q('当前配饰状态',s.current_accessory_state),q('当前丝袜状态',s.current_hosiery_state),q('当前鞋履状态',s.current_footwear_state),q('当前身体呈现',s.current_body_presentation),q('当前环境影响',s.current_environment_effect),q('当前补充状态',s.current_notes)
    ];
    return[];
  }

  function characters(root){return Object.entries(root?.characters||{}).filter(([,c])=>c?.profile_complete===true).map(([id,c])=>({id,c})).sort((a,b)=>(Date.parse(b.c?.updated_at||0)||0)-(Date.parse(a.c?.updated_at||0)||0))}
  function summary(c){const o=c?.profile?.outfit||{},h=c?.profile?.hair_makeup||{},a=[];if(o.outerwear?.status==='穿着')a.push(o.outerwear.full_name);a.push(o.hosiery?.status==='穿着'?o.hosiery.full_name:'未穿丝袜');a.push(o.footwear?.status==='穿着'?o.footwear.full_name:'未穿鞋履');if(h.hairstyle?.design)a.push(h.hairstyle.design);return a.filter(Boolean).slice(0,3).map(visibleText).join(' · ')||'完整视觉档案已建立'}

  function renderFacts(parent,c,tab){const card=make('div','avs25-fact-card');for(const f of facts(c,tab)){const row=make('div','avs25-fact-row'),k=make('div','avs25-fact-key',f.k),v=make('div','avs25-fact-value',visibleText(f.v));v.style.whiteSpace='pre-line';row.append(k,v);card.appendChild(row)}parent.appendChild(card)}
  function runtimeApi(){
    try{return globalThis.__AVS_V24_RUNTIME__?.api||null}catch(_){return null}
  }
  async function runFullRescan(){
    if(UI.rescanning)return;
    const api=runtimeApi();
    if(!api?.fullRescan){
      try{globalThis.toastr?.error?.('未检测到对应版本的AVS核心脚本。','AVS')}catch(_){}
      return;
    }
    UI.rescanning=true;render();
    try{await api.fullRescan()}catch(e){console.error('[AVS v2.5.1 Inspector] full rescan failed',e)}
    finally{UI.rescanning=false;render()}
  }
  async function runSelfCheck(){
    const api=runtimeApi();
    if(!api?.selfCheck){try{globalThis.toastr?.error?.('未检测到对应版本的AVS核心脚本。','AVS')}catch(_){};return}
    try{await api.selfCheck()}catch(e){console.error('[AVS v2.5.1 Inspector] self-check failed',e)}
  }
  function actionBar(){
    const bar=make('div','avs25-actions');
    const rescan=make('button','avs25-action avs25-primary',UI.rescanning?'重扫中…':'全量重扫');rescan.type='button';rescan.disabled=UI.rescanning;rescan.addEventListener('click',runFullRescan);
    const check=make('button','avs25-action','自检');check.type='button';check.disabled=UI.rescanning;check.addEventListener('click',runSelfCheck);
    bar.append(rescan,check);return bar;
  }

  function renderList(root){
    UI.content.replaceChildren();const list=characters(root),head=make('div','avs25-list-head'),diag=root?.runtime?.diagnostics||{};
    const health=root?.runtime?.health||'READY';
    const healthText=health==='PROCESSING'?'正在进行流式单次批量同步':health==='DEGRADED'?'本轮同步失败，可点击全量重扫':'后台同步正常';
    head.append(make('div','avs25-title','角色视觉档案'),make('div','avs25-sub',`已登记 ${list.length} 名女角色 · 状态版本 ${root?.$meta?.state_revision??0} · ${healthText}`));UI.content.appendChild(head);UI.content.appendChild(actionBar());
    if(health==='PROCESSING')UI.content.appendChild(make('div','avs25-sync','大模型正文已完成，AVS正在通过一次流式后台接口调用批量完成审查、档案补全与变量更新。'));
    if(health==='DEGRADED')UI.content.appendChild(make('div','avs25-warning','后台同步曾出现异常。系统不会对同一楼层反复轰炸接口；可在下一轮继续同步，或使用“AVS 全量重扫”手动重试。'));
    if(list.length>=5){const sw=make('div','avs25-search');sw.appendChild(svg('search'));const input=make('input');input.placeholder='搜索角色';input.value=UI.search;input.addEventListener('input',()=>{UI.search=input.value;render()});sw.appendChild(input);UI.content.appendChild(sw)}
    const q=UI.search.trim().toLocaleLowerCase(),shown=list.filter(x=>!q||String(x.c.identity?.name||'').toLocaleLowerCase().includes(q));
    if(!shown.length){UI.content.appendChild(make('div','avs25-empty',`尚未登记通过审查门并完成视觉档案的女角色。\n已检测模型正文 ${diag.assistant_turns_detected??0} 次 · 接口调用 ${diag.api_calls??0} 次 · 成功同步 ${diag.sync_successes??0} 次。\n最近批次：新登记 ${diag.last_batch_new??0} 名 · 更新 ${diag.last_batch_updated??0} 名 · 拒绝 ${diag.last_batch_rejected??0} 项。\n每条模型正文最多进行一次流式后台接口调用；失败楼层不会自动反复轰炸API。`));return}
    const box=make('div','avs25-char-list');for(const x of shown){const b=make('button','avs25-char-row');b.type='button';b.append(make('div','avs25-avatar',String(x.c.identity?.name||'?').slice(0,1)));const m=make('div','avs25-char-main');m.append(make('div','avs25-char-name',x.c.identity?.name||'未命名'),make('div','avs25-char-summary',summary(x.c)));b.append(m,make('div','avs25-chev','›'));b.addEventListener('click',()=>{UI.selectedId=x.id;UI.tab='overview';render()});box.appendChild(b)}UI.content.appendChild(box)
  }
  function renderDetail(root,c){
    UI.content.replaceChildren();const top=make('div','avs25-detail-head'),back=make('button','avs25-icon');back.type='button';back.appendChild(svg('back'));back.addEventListener('click',()=>{UI.selectedId=null;render()});
    const id=make('div','avs25-detail-id');id.append(make('div','avs25-detail-name',c.identity?.name||'未命名'),make('div','avs25-detail-meta',`${c.identity?.species||'未记录'} · 外貌年龄 ${c.identity?.visual_age?.min??'—'}—${c.identity?.visual_age?.max??'—'}岁`));top.append(back,id);UI.content.appendChild(top);UI.content.appendChild(actionBar());
    const tabs=make('div','avs25-tabs');for(const[key,label]of TABS){const b=make('button','avs25-tab',label);b.type='button';b.classList.toggle('active',UI.tab===key);b.addEventListener('click',()=>{UI.tab=key;render()});tabs.appendChild(b)}UI.content.appendChild(tabs);renderFacts(UI.content,c,UI.tab);UI.content.appendChild(make('div','avs25-footer',`状态版本 ${root?.$meta?.state_revision??0} · 只读查看`))
  }
  function render(){
    if(!UI.root||!UI.content)return;if(!contextActive()){unmount();return}const root=state();
    if(!UI.open){const rev=Number(root?.$meta?.state_revision??-1);UI.dot?.classList.toggle('on',UI.lastRevision>=0&&rev>UI.lastRevision);return}
    if(!root){UI.content.replaceChildren(make('div','avs25-empty','AVS后台正在初始化并扫描当前聊天。'));return}
    if(UI.selectedId&&root.characters?.[UI.selectedId])renderDetail(root,root.characters[UI.selectedId]);else{UI.selectedId=null;renderList(root)}
  }
  function openPanel(){UI.open=true;UI.panel.hidden=false;positionPanel();const r=state();UI.lastRevision=Number(r?.$meta?.state_revision??-1);UI.dot?.classList.remove('on');requestAnimationFrame(()=>{const x=UI.panel.getBoundingClientRect();if(x.width<100||x.height<100){UI.open=false;UI.panel.hidden=true;UI.ball.hidden=false;return}UI.ball.hidden=true;render()})}
  function closePanel(){UI.open=false;UI.panel.hidden=true;UI.ball.hidden=false;UI.selectedId=null;render()}

  function css(){return `
#${UI.rootId}{--bg:#fff;--fg:#171717;--sub:#737373;--line:rgba(0,0,0,.10);--soft:#f5f5f5;--warn:#fff5d6;--warnfg:#6b5200;--shadow:0 14px 42px rgba(0,0,0,.20);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Noto Sans SC","Microsoft YaHei",sans-serif;position:fixed;inset:0;z-index:2147483000;pointer-events:none;color:var(--fg)}
#${UI.rootId}.dark{--bg:#202123;--fg:#f5f5f5;--sub:#aaa;--line:rgba(255,255,255,.11);--soft:#2b2c2f;--warn:#4a3b0b;--warnfg:#ffe59a;--shadow:0 16px 48px rgba(0,0,0,.5)}
#${UI.rootId} *{box-sizing:border-box}.avs25-ball{pointer-events:auto;position:fixed;width:54px;height:54px;border-radius:50%;border:1px solid var(--line);background:var(--bg);color:var(--fg);box-shadow:0 7px 24px rgba(0,0,0,.22);font-weight:750;font-size:13px;touch-action:none;user-select:none;cursor:grab}.avs25-dot{position:absolute;right:3px;top:3px;width:9px;height:9px;border-radius:50%;background:#10a37f;border:2px solid var(--bg);opacity:0}.avs25-dot.on{opacity:1}
.avs25-panel{pointer-events:auto;position:fixed;background:var(--bg);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow);overflow:hidden;display:flex;flex-direction:column}.avs25-panel[hidden],.avs25-ball[hidden]{display:none!important}.avs25-head{height:55px;flex:0 0 auto;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 14px 0 18px}.avs25-brand{font-weight:750;font-size:15px}.avs25-brand span{font-weight:500;color:var(--sub);margin-left:8px}.avs25-icon{width:36px;height:36px;border:0;border-radius:10px;background:transparent;color:var(--fg);display:flex;align-items:center;justify-content:center;cursor:pointer}.avs25-icon:hover{background:var(--soft)}.avs25-icon svg,.avs25-search svg{width:19px;height:19px}.avs25-scroll{overflow:auto;padding:16px;min-height:0}
